SELECT  json_build_object('aggregate', json_build_object('count', COUNT(*), 'sum', json_build_object('id', sum("_root"."root.pg.id" ) ) ), 'nodes', coalesce(json_agg("root.f.nodes" ORDER BY "root.pg.id" ASC NULLS LAST), '[]' ) ) AS "root" FROM  (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.base"."id" AS "id", "_root.ar.nodes.comments_aggregate"."comments_aggregate" AS "comments_aggregate"       ) AS "_e"      ) ) AS "root.f.nodes", "_root.base"."id" AS "root.pg.id" FROM  (SELECT  *  FROM "public"."article"  WHERE (("public"."article"."author_id") = (('3')::integer))   ORDER BY "id" ASC NULLS LAST LIMIT 2 OFFSET 1) AS "_root.base" LEFT OUTER JOIN LATERAL (SELECT  json_build_object('aggregate', json_build_object('count', COUNT(*) ) ) AS "comments_aggregate" FROM  (SELECT  1  FROM  (SELECT  *  FROM "public"."comment"  WHERE ((("_root.base"."id") = ("article_id")) AND (EXISTS  (SELECT  1  FROM "public"."article" AS "__be_0_article" WHERE (((("__be_0_article"."id") = ("public"."comment"."article_id")) AND ('true')) AND (('true') AND (((("__be_0_article"."author_id") = (('3')::integer)) AND ('true')) AND ('true'))))     )))     ) AS "_root.ar.nodes.comments_aggregate.base"      ) AS "_root.ar.nodes.comments_aggregate"      ) AS "_root.ar.nodes.comments_aggregate" ON ('true')    ORDER BY "root.pg.id" ASC NULLS LAST  ) AS "_root"
